CREATE FUNCTION public.validate_occurrence_category() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=NEW.category_id AND active AND parent_id IS NULL) THEN RAISE EXCEPTION 'Categoria principal inválida'; END IF; IF NEW.subcategory_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.categories WHERE id=NEW.subcategory_id AND active AND parent_id=NEW.category_id) THEN RAISE EXCEPTION 'A subcategoria deve pertencer à categoria selecionada'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.validate_occurrence_category() FROM PUBLIC; CREATE TRIGGER validate_occurrence_category BEFORE INSERT OR UPDATE OF category_id,subcategory_id ON public.occurrences FOR EACH ROW EXECUTE FUNCTION public.validate_occurrence_category();